  auto number=[&f](const string&name){string key="\""+name+"\":";size_t a=f.find(key);return a==string::npos?0ULL:stoull(f.substr(a+key.size()));};
  auto real=[&f](const string&name){string key="\""+name+"\":";size_t a=f.find(key);return a==string::npos?0.0:stod(f.substr(a+key.size()));};
