   string port=e=="PFC_RX"?text("paused_port"):text("port");bool on=(e=="PFC_RX"||e=="NIC_PFC_RX")&&f.find("\"xoff\":true")!=string::npos;auto it=paired_pause_active.find(port);
   if(it!=paired_pause_active.end()){double start=it->second.first,end=it->second.second;paired_pause_active.erase(it);if(end<t){paired_pause_closed[port].push_back(make_pair(start,end));start=t;}if(on)paired_pause_active[port]=make_pair(start,max(end,t+8.0));else if(min(end,t)>start)paired_pause_closed[port].push_back(make_pair(start,min(end,t)));}
