   string flow=text("flow");/* Every named QP has actual pause and backlog coverage. */
   string port=text("hop");double wait=real("queue_wait_us"),begin=t-wait;paired_queue_sum[flow]+=wait;paired_queue_max[flow]=max(paired_queue_max[flow],wait);
   auto add=[&](double a,double b){a=max(a,begin);b=min(b,t);if(b>a){paired_wait_sum[flow]+=b-a;paired_flow_wait[flow].push_back(make_pair(a,b));if(port.find("spine")!=string::npos)paired_flow_fabric_wait[flow].push_back(make_pair(a,b));}};
