 void mprdma_burst_tick(int flow,uint64_t generation){if(recovery_burst_epoch[flow]!=generation||!mprdma_states[flow]->recovery_active())return;for(int i=0;i<2;i++){uint64_t seq;if(!mprdma_states[flow]->next_retransmission(seq))break;auto it=original_packets.find(make_pair(flow,seq));if(it!=original_packets.end()){LIGHT_TRACE("mprdma_burst_timer","\"flow\":\""+flows[flow].name+"\",\"retransmit_psn\":"+to_string(it->second->psn)+",\"retransmit_seq\":"+to_string(seq)+",\"interval_us\":2.5");request_retransmit(it->second,"mprdma_burst_timer");}}if(mprdma_states[flow]->recovery_active())schedule(ev.now()+timeFromNs(2500),[this,flow,generation](){mprdma_burst_tick(flow,generation);});}
