 void load_traffic_csv(){
  ifstream input(traffic_csv);if(!input)throw runtime_error("cannot open traffic CSV");
  string line;getline(input,line);if(!line.empty()&&line.back()=='\r')line.pop_back();
  if(line!="flow,role,communication_group,src,dst,spine,payload_bytes,start_us,qp_wire_pacing_gbps")throw runtime_error("invalid traffic CSV header");
  set<string> names;while(getline(input,line)){
   if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())continue;
   stringstream row(line);vector<string> c;string field;while(getline(row,field,','))c.push_back(field);
   if(c.size()!=9)throw runtime_error("invalid traffic CSV row");
   int src=stoi(c[3]),dst=stoi(c[4]),spine=stoi(c[5]);uint64_t bytes=stoull(c[6]);double start=stod(c[7]),rate=stod(c[8]);
   if(src<0||dst<0||src>=(int)nic_count||dst>=(int)nic_count||src==dst||spine!=ecmp(src,dst)||!bytes||bytes%PAYLOAD||start<0||rate<=0||!names.insert(c[0]).second||(c[1]!="healthy"&&c[1]!="background"))throw runtime_error("invalid traffic CSV value or ECMP mapping");
   add_flow(c[0],c[1]=="healthy"?ROLE_HEALTHY:ROLE_BACKGROUND,src,dst,spine,bytes/PAYLOAD,timeFromUs(start),rate);
  }
  if(flows.empty())throw runtime_error("empty traffic CSV");
  LIGHT_TRACE("traffic_input","\"path\":\""+traffic_csv+"\",\"flows\":"+to_string(flows.size())+",\"route_validation\":\"existing_ecmp_hash\"");
 }
