   int vp=max_element(counts,counts+8)-counts,rp=0;while(rp<8&&counts[rp])rp++;if(rp==8)rp=(vp+1)%8;
   uint32_t start=scenario=="pfc_victim"?180:100;uint64_t packets=scenario=="pfc_victim"?256:64;add_flow("victim",ROLE_DIAGNOSTIC,0,29,vp,packets,us(start));add_flow("reference",ROLE_DIAGNOSTIC,1,17,rp,packets,us(start));
