  for(size_t i=0;i<flows.size();i++){FlowState*f=&flows[i];trace(f->start,"path","\"flow\":\""+f->name+"\",\"flow_role\":\""+flow_role_name(f->role)+"\",\"src\":"+to_string(f->src)+",\"dst\":"+to_string(f->dst)+",\"spine\":"+to_string(f->spine));schedule(f->start,[this,f](){send_next(f,0);});}
