   schedule(us(link_down_us),[this](){link_down[fault_port]=true;++link_failure_generation[fault_port];LIGHT_TRACE("link_down","\"port\":\""+fault_port+"\",\"serializer_busy\":"+(ports[fault_port].busy?"true":"false")+",\"queued_data\":"+to_string(ports[fault_port].data.size())+",\"queued_control\":"+to_string(ports[fault_port].control.size()));if(scenario=="link_fault_notify")schedule(ev.now()+us(link_notify_delay_us),[this](){LIGHT_TRACE("link_state_notification_send","\"port\":\""+fault_port+"\",\"state\":\"down\"");transmit("spine0-leaf0-control",64,[this](){notified_bad_spines.insert(0);previously_notified_spines.insert(0);LIGHT_TRACE("link_state_notification_arrive","\"port\":\""+fault_port+"\",\"state\":\"down\",\"scope\":\"source_leaf0\"");});});});
